<template>
<el-dialog :model-value="modelValue" title="供应商入库差异" width="95%" top="5vh" class="receipt-difference-dialog" @update:model-value="emit('update:modelValue',$event)">
 <el-alert v-if="error" :title="error" type="error" :closable="false"/>
 <div class="filters"><el-input v-model="supplier" placeholder="搜索供应商名称" clearable @input="clearParty"/><el-input v-model="keyword" placeholder="发货单 / 采购单 / 入库单 / 备注" clearable @keyup.enter="load"/><span class="filter-label">入库日期</span><el-date-picker v-model="dates" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" range-separator="至"/><el-select v-model="status"><el-option label="全部" value=""/><el-option label="待处理" value="pending"/><el-option label="已处理" value="processed"/></el-select><el-button @click="load">查询</el-button></div>
 <template v-if="!party"><p class="view-heading">供应商汇总 <span>共 {{filteredSuppliers.length}} 组 · 点击查看差异明细</span></p><el-button link @click="summaryOpen=!summaryOpen">{{summaryOpen?'收起供应商汇总':'展开供应商汇总'}}</el-button><el-table v-show="summaryOpen" :data="pagedSuppliers" max-height="480" v-loading="loading" border @row-click="chooseSupplier" class="supplier-table"><el-table-column prop="supplier_name" label="供应商"/><el-table-column label="币种"><template #default="{row}">{{row.currency||'待确认'}}</template></el-table-column><el-table-column label="多到金额" align="right"><template #default="{row}"><span :title="row.over_amount">{{money(row.over_amount)}}</span></template></el-table-column><el-table-column label="少到金额" align="right"><template #default="{row}"><span :title="row.short_amount">{{money(row.short_amount)}}</span></template></el-table-column><el-table-column prop="pending_count" label="待处理明细数" align="right"/><el-table-column label="操作" width="130"><template #default="{row}"><el-button link type="primary" @click.stop="chooseSupplier(row)">查看单据明细</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="supplierPage" :page-size="10" :total="filteredSuppliers.length" layout="total, prev, pager, next"/></template>
 <template v-else><div class="view-heading"><el-button @click="clearParty">返回供应商汇总</el-button><strong>{{party.supplier_name}} · {{party.currency||'币种待确认'}}</strong><span>共 {{visibleRows.length}} 条差异明细</span></div><p class="hint">勾选明细后预览处理；金额默认显示两位小数，悬停查看原始精度。</p>
 <el-button link @click="detailOpen=!detailOpen">{{detailOpen?'收起差异明细':'展开差异明细'}}</el-button><el-table v-show="detailOpen" :data="visibleRows" row-key="key" max-height="450" border v-loading="loading" @selection-change="selected=$event"><el-table-column type="selection" :selectable="r=>r.status!=='unassigned'&&!!r.currency"/>
 <el-table-column prop="supplier_name" label="供应商"/><el-table-column label="发货单"><template #default="{row}"><el-button link @click="emit('open',{kind:'shipment',id:row.shipment_id,number:row.shipment_number})">{{row.shipment_number}}</el-button></template></el-table-column>
 <el-table-column label="入库单"><template #default="{row}"><el-button link @click="emit('open',{kind:'inbound',id:row.inbound_id,number:row.inbound_number})">{{row.inbound_number}}</el-button></template></el-table-column>
 <el-table-column label="币种"><template #default="{row}">{{row.currency||'待确认'}}<el-button v-if="!row.currency&&row.shipment_id" link type="primary" @click="maintainCurrency(row)">维护付款币种</el-button></template></el-table-column><el-table-column label="新 / 旧 SKU" min-width="190"><template #default="{row}"><div class="sku-pair"><div><span>新SKU：</span>{{row.new_sku||row.sku||'—'}}</div><div><span>旧SKU：</span>{{row.old_sku||'—'}}</div></div></template></el-table-column><el-table-column prop="expected_quantity" label="发货"/><el-table-column prop="received_quantity" label="实收"/><el-table-column label="差异"><template #default="{row}">{{row.type==='over'?'多到':'少到'}} {{row.difference_quantity}}</template></el-table-column><el-table-column label="单价" align="right"><template #default="{row}"><span :title="row.unit_price">{{money(row.unit_price)}}</span></template></el-table-column><el-table-column label="差异金额" align="right"><template #default="{row}"><span :title="row.amount">{{money(row.amount)}}</span></template></el-table-column><el-table-column label="状态"><template #default="{row}">{{({pending:"待处理",processed:"已处理",unassigned:"待归属"})[row.status]||row.status}}</template></el-table-column>
 <el-table-column label="原处理"><template #default="{row}"><el-button v-if="row.type==='over'&&row.history_candidates?.length" link @click="openHistory(row)">关联原历史结清</el-button><el-button v-if="row.decision_id" link @click="reverse(row)">撤销原处理</el-button><el-select v-if="row.status==='unassigned'" @change="id=>assign(row,id)"><el-option v-for="c in row.assignment_candidates||[]" :key="c.shipment_id" :value="c.shipment_id" :label="c.supplier_name+' / '+c.shipment_number"/></el-select></template></el-table-column></el-table>
 <el-button link @click="actionsOpen=!actionsOpen">{{actionsOpen?'收起处理区域':'展开处理区域'}} · 已选 {{selected.length}} 条</el-button><div v-show="actionsOpen" class="filters action-bar"><span>已选 {{selected.length}} 条</span><el-select v-model="option"><el-option label="按净差结算" value="wrong_item_net_settlement"/><el-option label="多到供应商免收" value="supplier_waived"/><el-option label="历史已结清无需补付" value="historical_paid"/><el-option label="继续待核" value="pending_review"/></el-select><el-input v-model="reason" placeholder="处理原因（必填）"/><el-checkbox v-model="adjustPrevious">调整原处理</el-checkbox><el-button :disabled="!selected.length||busy" @click="preview">预览处理</el-button></div></template>
 <el-dialog v-model="historyOpen" append-to-body title="关联原历史结清" width="650px"><p>请核实原凭证对应本条多到商品的金额。关联后通过“调整原处理”执行结算调整。</p><el-select v-model="historyRevision" placeholder="选择原历史结清凭证"><el-option v-for="c in historyRow?.history_candidates||[]" :key="c.revision_id" :value="c.revision_id" :label="(c.reference_number||'历史凭证')+' · 金额 '+c.amount+' · '+(c.notes||'')"/></el-select><el-input v-model="historyAmount" placeholder="分配到本条多到差异的金额"/><el-input v-model="historyReason" placeholder="核实依据（必填）"/><template #footer><el-button @click="historyOpen=false">取消</el-button><el-button type="primary" :loading="busy" @click="bindHistory">确认关联</el-button></template></el-dialog><el-dialog v-model="previewOpen" append-to-body title="确认差异处理" width="650px"><p>原应付 {{result.due_before}} → 调整后应付 {{result.due_after}}</p><p>实际已付 {{result.cash_paid}} · 历史结清 {{result.historical_settled}}</p><p>调整后剩余应付 {{result.remaining_after}} · 预付余额 {{result.prepaid_balance_after}}</p><p>少到 {{result.short_amount}} · 多到 {{result.over_amount}}</p><p>净差 {{result.net_difference_amount}} · 本次实际调整 {{result.incremental_adjustment}}</p><el-table v-if="result.previous_decisions?.length" :data="result.previous_decisions" border><el-table-column prop="option" label="原处理方式"/><el-table-column prop="reason" label="原处理依据"/><el-table-column prop="created_by" label="操作人"/><el-table-column prop="created_at" label="处理时间"/><el-table-column prop="amount" label="原应付调整"/></el-table><el-table v-if="result.history_adjustments?.length" :data="result.history_adjustments" border><el-table-column prop="revision_id" label="原历史结清版本"/><el-table-column prop="reduction" label="本次撤销历史结清金额"/></el-table><p v-if="adjustPrevious">将撤销所选差异原结算处理并保留凭证及操作记录；实际转账不冲销。</p><p>实际付款保留；本次结算调整不改变库存。已扣减部分不重复扣减。</p><el-alert v-if="result.requires_adjust_previous" title="存在原处理记录，需要勾选调整原处理后重新预览" type="warning"/><template #footer><el-button @click="previewOpen=false">返回</el-button><el-button type="primary" :loading="busy" :disabled="result.requires_adjust_previous&&!adjustPrevious" @click="settle">确认处理</el-button></template></el-dialog>
</el-dialog>
</template>
<script setup>
import {ref,computed,watch} from 'vue';
import {ElMessageBox} from 'element-plus';
import {requestApi} from '../../api/request';
const props=defineProps({modelValue:Boolean,countryId:[Number,String]});const emit=defineEmits(['update:modelValue','open','updated']);
const supplier=ref(''),dates=ref([]),status=ref(''),suppliers=ref([]),rows=ref([]),selected=ref([]),loading=ref(false),busy=ref(false),error=ref(''),option=ref('wrong_item_net_settlement'),reason=ref(''),adjustPrevious=ref(false),previewOpen=ref(false),result=ref({}),party=ref(null);let generation=0,previewBody=null,requestKey='';
const supplierPage=ref(1),keyword=ref(''),summaryOpen=ref(true),detailOpen=ref(true),actionsOpen=ref(true);
const filteredSuppliers=computed(()=>suppliers.value.filter(r=>!supplier.value.trim()||String(r.supplier_name||'').toLowerCase().includes(supplier.value.trim().toLowerCase())));
const pagedSuppliers=computed(()=>filteredSuppliers.value.slice((supplierPage.value-1)*10,supplierPage.value*10));
const visibleRows=computed(()=>rows.value.filter(r=>party.value&&r.supplier_id===party.value.supplier_id&&(r.currency||null)===(party.value.currency||null)&&(!supplier.value.trim()||String(r.supplier_name||'').toLowerCase().includes(supplier.value.trim().toLowerCase()))));
function money(value){return value==null?'待核实':Number(value).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});}
function clearParty(){party.value=null;selected.value=[];supplierPage.value=1;}

const historyOpen=ref(false),historyRow=ref(null),historyRevision=ref(null),historyAmount=ref(''),historyReason=ref('');
const base='/api/internal/supply-chain/v2/receipt-differences/';
async function api(url,method='get',data,params){const r=await requestApi({url:base+url,method,data,params,headers:method==='post'?{'Idempotency-Key':requestKey||crypto.randomUUID()}:undefined});if(!r?.success)throw new Error(r?.message||'入库差异操作失败');return r.data;}
async function load(){const token=++generation;loading.value=true;error.value='';try{const d=await api('','get',undefined,{query:keyword.value.trim()||undefined,country:props.countryId||undefined,start_date:dates.value?.[0],end_date:dates.value?.[1],status:status.value||undefined});if(token!==generation)return;suppliers.value=d.suppliers||[];rows.value=d.rows||[];selected.value=[];supplierPage.value=1;}catch(e){error.value=e.message;}finally{if(token===generation)loading.value=false;}}
function openHistory(r){historyRow.value=r;historyRevision.value=null;historyAmount.value=r.amount;historyReason.value='';historyOpen.value=true;}
async function bindHistory(){if(!historyRevision.value||!historyReason.value.trim()||!(Number(historyAmount.value)>0)){error.value='请核实原凭证、分配金额及依据';return;}busy.value=true;try{requestKey=crypto.randomUUID();await api('history-bind/','post',{key:historyRow.value.key,revision_id:historyRevision.value,amount:historyAmount.value,reason:historyReason.value});historyOpen.value=false;await load();emit('updated');}catch(e){error.value=e.message;}finally{busy.value=false;}}
function maintainCurrency(r){emit('update:modelValue',false);emit('open',{kind:'shipment',id:r.shipment_id,number:r.shipment_number,initialPanel:'payment'});}
function chooseSupplier(r){party.value=r;selected.value=[];}
function body(){return {keys:selected.value.map(r=>r.key),option:option.value,reason:reason.value,expected_versions:Object.fromEntries(selected.value.map(r=>[r.key,r.version])),adjust_previous:adjustPrevious.value};}
async function preview(){error.value='';if(new Set(selected.value.map(r=>r.supplier_id+'|'+r.currency)).size!==1){error.value='请选择同一供应商、同一币种的差异';return;}if(!reason.value.trim()){error.value='请填写处理原因';return;}busy.value=true;try{previewBody=body();result.value=await api('preview/','post',previewBody);requestKey=crypto.randomUUID();previewOpen.value=true;}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function settle(){busy.value=true;try{await api('settle/','post',{...previewBody,preview_token:result.value.preview_token});previewOpen.value=false;await load();emit('updated');}catch(e){error.value=e.message;previewOpen.value=false;}finally{busy.value=false;}}
async function reverse(r){try{const p=await ElMessageBox.prompt('填写撤销原因，原凭证和操作记录将保留','撤销原处理',{inputValidator:v=>!!v?.trim()||'请填写原因'});requestKey=crypto.randomUUID();await api(r.decision_id+'/reverse/','post',{reason:p.value});await load();emit('updated');}catch(e){if(e?.message)error.value=e.message;}}
async function assign(r,id){try{const p=await ElMessageBox.prompt('说明额外商品归属依据','确认供应商归属',{inputValidator:v=>!!v?.trim()||'请填写依据'});requestKey=crypto.randomUUID();await api('assign/','post',{key:r.key,shipment_id:id,reason:p.value});await load();}catch(e){if(e?.message)error.value=e.message;}}
watch(()=>[props.modelValue,props.countryId],()=>{if(props.modelValue){party.value=null;load();}else generation++;});
</script>
<style scoped>.sku-pair{line-height:1.6;overflow-wrap:anywhere}.sku-pair span{color:#64748b;white-space:nowrap}
.filters{display:flex;gap:12px;margin:12px 0;align-items:center;flex-wrap:wrap}.filters>.el-input{width:230px;flex:none}.filters>.el-select{width:160px;flex:none}.filters :deep(.el-date-editor){width:300px;max-width:100%;flex:none}.filter-label,.hint,.view-heading span{color:#64748b;font-size:13px}.view-heading{display:flex;align-items:center;gap:12px;margin:16px 0;font-weight:600}.supplier-table :deep(.el-table__row){cursor:pointer}.el-pagination{justify-content:flex-end;margin-top:14px}.action-bar{position:sticky;bottom:0;background:#fff;border-top:1px solid #e5e7eb;padding:12px 0;z-index:2}.action-bar>.el-select{width:200px}.action-bar>.el-input{width:260px}@media(max-width:760px){.filters>.el-input,.filters :deep(.el-date-editor){width:100%}.view-heading{flex-wrap:wrap}}
</style>
